import { parseStructured } from '../dsl';
import { VOA_STORIES } from '../voa.generated';
import type { StructuredQuestion } from '../../types';

/**
 * Authentic English B Paper 2-style reading: Voice of America Learning English stories (public
 * domain, verbatim, generated by scripts/voa_resources.py) with questions written for the app.
 * Paragraphs are numbered so questions can refer to them.
 */
const SETS: { key: string; questions: string }[] = [
  {
    key: 'goddard',
    questions: String.raw`
@struct HI
Q: Read the text and answer the questions.
a) [1] According to paragraph 3, how does NASA describe Goddard? Complete: "the father of ___".
~ modern rocket propulsion | the father of modern rocket propulsion | rocket propulsion
M: modern rocket propulsion (1)
b) [1] In what year did Goddard launch the world's first liquid-fuel rocket?
= 1926 abs=0
M: 1926 ("The next year", after 1925) (1)
c) [1] Which word in paragraph 6 shows that Goddard's fuels before 1925 formed "a hard substance"?
~ solid | solid fuels
M: solid (1)
d) [1] Which institution gave Goddard money and support during his early research?
~ Smithsonian | the Smithsonian | Smithsonian Institution | the Smithsonian Institution | U.S. Smithsonian Institution | the U.S. Smithsonian Institution
M: the (U.S.) Smithsonian Institution (1)
e) [1] What was Goddard trying to send higher than balloons could fly?
~ weather recording instruments | weather instruments | instruments
M: weather recording instruments (1)
f) [2] Why did many people think Goddard was foolish?
M: he suggested a rocket could one day reach the moon (1) ¶ which seemed impossible at the time (1)
g) [1] True or false: Goddard's ideas are no longer used today. Justify your answer with words from the text.
M: False: "Many of Goddard's ideas are still used in rocket development." (both needed) (1)
h) [2] Explain what the writer means by "every rocket that flies today could be considered a Goddard rocket".
M: modern rockets still rely on principles he developed (1) ¶ e.g. liquid fuel / the mathematics of rocket flight, so his work underlies all of them (1)
`,
  },
  {
    key: 'gettysburg',
    questions: String.raw`
@struct EX
Q: Read the text and answer the questions.
a) [1] In which state is the Gettysburg National Military Park?
~ Pennsylvania
M: Pennsylvania (1)
b) [1] Who commanded the United States Army of the Potomac?
~ George Meade | General George Meade | Meade | General Meade
M: (General) George Meade (1)
c) [2] According to paragraph 4, what did Lee believe a Southern win on Northern land would achieve?
M: force a negotiated settlement of the Civil War (1) ¶ independence for the Confederate States (1)
d) [1] About how many soldiers fought in the battle?
= 170000 rel=0.01
M: about 170,000 (1)
e) [1] How many days did the battle last?
= 3 abs=0
M: three days (1 to 3 July 1863) (1)
f) [1] What is special about a cyclorama painting?
M: it completely surrounds the people looking at it (1)
g) [1] What does the "High Water Mark" refer to?
M: the point closest to the northern lines that the Confederate soldiers reached, i.e. the furthest they advanced (1)
h) [1] For how many minutes did Lincoln speak at Gettysburg?
= 2 abs=0 unit=min
M: two minutes (1)
`,
  },
  {
    key: 'washington',
    questions: String.raw`
@struct SO
Q: Read the text and answer the questions.
a) [1] In what year did Washington's presidency end?
= 1797 abs=0
M: 1797 (1)
b) [1] Why did Washington accept the job of president even though he wanted to retire?
~ duty | as his duty | his duty | it was his duty | he saw it as his duty
M: he accepted it as his duty (1)
c) [2] Name TWO institutions Washington established or created as president.
M: any two: the cabinet; the nation's official money; a six-member Supreme Court; the Department of Foreign Affairs (now the State Department) (1 + 1)
d) [1] How many members did Washington's Supreme Court have?
= 6 abs=0
M: six (1)
e) [1] According to historian Joseph Ellis, what was one of the best things about Washington?
~ his ability to give up power | ability to give up power | giving up power | the ability to give up power
M: his ability to give up power (1)
f) [1] Which phrase in paragraph 3 shows that Washington wanted later presidents to continue his work? Complete: "continue to ___".
~ build on what he began | continue to build on what he began
M: build on what he began (1)
g) [1] What did Washington's will order?
M: that his slaves be freed after his wife's death (1)
h) [1] How old was Washington when he died?
= 67 abs=0
M: 67 (1)
`,
  },
];

export const englishVoaReading: StructuredQuestion[] = SETS.map(({ key, questions }) => {
  const story = VOA_STORIES[key];
  if (!story) throw new Error(`Missing VOA story ${key}`);
  const [q] = parseStructured('english', questions);
  const text = story.paragraphs
    .slice(0, -1) // drop the presenter's sign-off ("I'm …")
    .map((p, i) => `[${i + 1}] ${p}`)
    .join('\n\n');
  return {
    ...q,
    prompt: `**"${story.title}"** (Voice of America Learning English, ${story.date}; public domain)\n\n${text}\n\n${q.prompt}`,
    solution: `Source: ${story.url}. ${story.credit}`,
  };
});
